const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2019-09-01';
  const point1 = ee.Geometry.Point([-58.944881, 50.282684]); // (long, lat) for (50.282684, -58.944881)
  const point2 = ee.Geometry.Point([-54.128047, 50.415337]); // (long, lat) for (50.415337, -54.128047)
  const band = 'Oa05_reflectance'; // Green band (560 nm) - often sensitive to suspended matter for water color.
  const scale = 1000; // Use a reasonable scale for reduceRegion to prevent timeouts.

  // Sentinel-3 OLCI Level-2 Water Full Resolution (WFR) Collection
  let collection = ee.ImageCollection('COPERNICUS/S3/OLCI')
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  // Define a cloud/land/invalid mask function
  const applyQualityMask = function(image) {
    // Quality flags from S3 OLCI Level-2
    // bit 0: CLOUD_S3_OLCI (1 = cloud)
    // bit 1: LAND_S3_OLCI (1 = land)
    // bit 3: INVALID_S3_OLCI (1 = invalid measurement)
    // We are looking for water, so mask out cloud, land, and invalid pixels.
    const qualityFlags = image.select('quality_flags');
    const cloudMask = qualityFlags.bitwiseAnd(1).eq(0); // 0 means no cloud
    const landMask = qualityFlags.bitwiseAnd(2).eq(0);  // 0 means no land
    const invalidMask = qualityFlags.bitwiseAnd(8).eq(0); // 0 means not invalid

    return image.updateMask(cloudMask.and(landMask).and(invalidMask));
  };

  // 2. Data Acquisition & Check for Point 1
  let col1 = collection.filterBounds(point1).map(applyQualityMask);
  let count1 = col1.size().getInfo();

  if (count1 === 0) {
    console.log("No OLCI images found for Point 1 on 2019-09-01 after filtering.");
    console.log("C1");
    return;
  }
  let image1 = col1.median(); // Use median to get a single composite image if multiple exist

  // 3. Data Acquisition & Check for Point 2
  let col2 = collection.filterBounds(point2).map(applyQualityMask);
  let count2 = col2.size().getInfo();

  if (count2 === 0) {
    console.log("No OLCI images found for Point 2 on 2019-09-01 after filtering.");
    console.log("C1");
    return;
  }
  let image2 = col2.median();

  // 4. Processing and Calculation for Point 1
  let pixelCount1 = image1.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1,
    scale: scale,
    maxPixels: 1e9
  }).get(band).getInfo();

  if (pixelCount1 === 0) {
    console.log(`Point 1: No valid pixels for ${band} after masking.`);
    console.log("C2");
    return;
  }

  let value1 = image1.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: scale,
    maxPixels: 1e9
  }).get(band).getInfo();

  // 5. Processing and Calculation for Point 2
  let pixelCount2 = image2.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2,
    scale: scale,
    maxPixels: 1e9
  }).get(band).getInfo();

  if (pixelCount2 === 0) {
    console.log(`Point 2: No valid pixels for ${band} after masking.`);
    console.log("C2");
    return;
  }

  let value2 = image2.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: scale,
    maxPixels: 1e9
  }).get(band).getInfo();

  // 6. Validation & Final Answer
  if (value1 === null || isNaN(value1) || value2 === null || isNaN(value2)) {
    console.log("Calculation resulted in Null/NaN for one or both points.");
    console.log("C3");
    return;
  }

  // "Milky" implies higher reflectance.
  const isMoreMilky = value1 > value2;

  console.log(`Point 1 Reflectance (Oa05): ${value1.toFixed(4)} (Pixels: ${pixelCount1})`);
  console.log(`Point 2 Reflectance (Oa05): ${value2.toFixed(4)} (Pixels: ${pixelCount2})`);
  console.log(`Is Point 1 more milky than Point 2? ${isMoreMilky ? 'Yes' : 'No'}`);

  if (isMoreMilky) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
